#!/usr/bin/env node
/* Reconciles phase-one source IDs with JSON lines emitted by latency runner. */
const fs=require('node:fs');
const [inventoryFile,runnerFile,outFile]=process.argv.slice(2);
if(!inventoryFile||!runnerFile||!outFile)throw Error('usage: node interaction_inventory_reconcile.cjs inventory.json runner.log output.json');
const inventory=JSON.parse(fs.readFileSync(inventoryFile,'utf8'));
const reports=[];for(const line of fs.readFileSync(runnerFile,'utf8').split(/\r?\n/)){const at=line.indexOf('{');if(at<0)continue;try{const x=JSON.parse(line.slice(at)),report=x.report||x;if(Array.isArray(report.seenControls))reports.push(report);}catch{}}
const seen=new Set(reports.flatMap(r=>r.seenControls||[])),fired=new Set(reports.flatMap(r=>r.firedControlIds||[]).map(x=>x.replace(/#on[A-Z][\w$-]*$/,''))),gaps=reports.flatMap(r=>r.untaggedInteractive||[]);
const trusted=reports.flatMap(r=>r.trusted_interactions||[]), scopedFiles=(process.env.AGENTNET_INTERACTION_SCOPE_FILES||'').split(',').filter(Boolean), rows=inventory.controls.filter(x=>x.population==='comic-react'), byFile=new Map();for(const row of rows){const key=row.source_ref.path;(byFile.get(key)||byFile.set(key,[]).get(key)).push(row);}
const attempts=id=>trusted.filter(x=>x.control_id===id), executed=id=>attempts(id).some(x=>x.status==='executed-pass'), failed=id=>!executed(id)&&attempts(id).some(x=>['executed-fail','failed'].includes(x.status)), unreachableRow=id=>!executed(id)&&!failed(id)&&attempts(id).some(x=>['unreachable','not_run'].includes(x.status)), dimensions=(id)=>{const a=attempts(id),seenKinds=new Set(a.map(x=>x.input_kind));return{normal_history:'not_run',history_10x:'not_run',cold:'not_run',warm:a.length?'run':'not_run',sync:'not_run',offline:'not_run',failing_backend:'not_run',touch:seenKinds.has('tap')?'run':'not_run',keyboard:seenKinds.has('keyboard')?'run':'not_run',platform_apply:'not_run',native_db_sync_contention:'not_run'};};
const summary=(name,items)=>{const ids=items.map(x=>x.definition_id),ownGaps=gaps.filter(g=>g.nearest_control&&ids.includes(g.nearest_control));return{feature_file:name,inventory:ids.length,rendered:ids.filter(x=>seen.has(x)||attempts(x).some(a=>a.status!=='unreachable')).length,fired_trusted:ids.filter(x=>attempts(x).some(a=>a.fired_trusted)).length,change_asserted:ids.filter(x=>attempts(x).some(a=>a.change_asserted)).length,within_bound:ids.filter(executed).length,failed:ids.filter(failed).length,not_executed:ids.filter(x=>!executed(x)&&!failed(x)&&!unreachableRow(x)).length,unreachable:ids.filter(unreachableRow).length,never_rendered:ids.filter(x=>!seen.has(x)&&!attempts(x).some(a=>a.status!=='unreachable')),rendered_not_fired:ids.filter(x=>(seen.has(x)||attempts(x).length)&&!attempts(x).some(a=>a.fired_trusted)),untagged_rendered:ownGaps,dimensions:Object.fromEntries(items.map(x=>[x.definition_id,dimensions(x.definition_id)]))};};
const files=[...byFile].sort(([a],[b])=>a.localeCompare(b)).map(([file,items])=>summary(file,items)), scopedRows=rows.filter(r=>scopedFiles.some(file=>r.source_ref.path.endsWith('/'+file)));
const applicability_rule={navigation_or_read_only:'normal and 10x history; cold and warm view; synchronization/catch-up; touch and keyboard where exposed; platform apply where platform-owned.',text_or_selection:'normal and 10x history; cold and warm view; synchronization/catch-up; repeated input; keyboard and touch variants; platform apply where exposed.',local_mutation:'normal and 10x history; cold and warm view; synchronization/catch-up; repeated input; offline and failing backend/recovery; touch and keyboard where exposed; platform apply where platform-owned.',permission_or_capability:'normal and 10x history where the screen contains history; cold and warm view; synchronization/catch-up; capability/permission boundary plus refusal/recovery; touch and keyboard where exposed; platform apply where platform-owned.',native_bridge:'native platform apply plus its applicable normal/10x, cold/warm, synchronization, offline/failing and input-mode dimensions.'};
const unreachable=scopedRows.filter(r=>unreachableRow(r.definition_id)||!attempts(r.definition_id).length).map(r=>({control_id:r.definition_id,file:r.source_ref.path,line:r.source_ref.line,reason:attempts(r.definition_id).find(a=>a.status==='unreachable')?.reason||(seen.has(r.definition_id)?'rendered in fixture but no trusted-input fixture state':'fixture state path not run')}));
const result={schema:'agentnet-interaction-reconciliation/v2',review:{complete:false},reports:reports.length,input_dispatch:[...new Set(reports.map(r=>r.inputDispatch))],comic_react:{total:summary('TOTAL',rows),scope:summary('SCOPE',scopedRows),by_feature_file:files,trusted_interactions:trusted,unreachable},unattributed_untagged_rendered:gaps.filter(g=>!g.nearest_control),populations_without_rendered_binding:['overlay','standalone','static','native-desktop','native-android'],applicability_rule,notes:'Only trusted Playwright input plus an asserted visible local change qualifies execution. Mocked fixture cannot prove native DB/sync contention.'};
fs.writeFileSync(outFile,JSON.stringify(result,null,2)+'\n');
const brief=s=>Object.fromEntries(['inventory','rendered','fired_trusted','change_asserted','within_bound','failed','not_executed','unreachable'].map(k=>[k,s[k]]));
console.log(JSON.stringify({reports:reports.length,comic:brief(result.comic_react.total),scope:brief(result.comic_react.scope),unreachable:unreachable.length,untagged:gaps.length}));
